-- build_conn_zurvan.sql  (GENERATED by gen_roster.py conn_zurvan) — v1.80.0
-- 2 entities, 4 edges, 0 new periods, 0 new sources. Idempotent + self-validating.
BEGIN;

CREATE TEMP TABLE _e(id text,name text,etype text,cat text,trad text,dom text,conf text,note text) ON COMMIT DROP;
INSERT INTO _e VALUES
 ('ENT_ZOR_ZURVAN_AKARANA','Zurvan akarana','Aspect of deity','Time Deity','Zoroastrian','boundless time; infinity; eternity','B','Zurvan akarana, ''Boundless/Infinite Time'' — the unconditioned, eternal aspect of Zurvan from which the cosmos and the finite world-cycle proceed in Zurvanite speculation (Zaehner, Zurvan, esp. pp. 89-105 on the two zurvans).'),
 ('ENT_ZOR_ZURVAN_DAREGHO','Zurvan daregho-chvadhata','Aspect of deity','Time Deity','Zoroastrian','finite time; time of long dominion; the world-age','B','Zurvan daregho-chvadhata, ''Time of Long Dominion'' — the finite, measured time (the 9,000/12,000-year world-cycle) into which Boundless Time issues so that the conflict of Ohrmazd and Ahriman can be played out and resolved (Zaehner, Zurvan, pp. 89-105, 219ff.).');

INSERT INTO entities (entity_id,canonical_name,tradition,entity_type,category,primary_domains,cult_scope,evidence_confidence,review_status,inclusion_basis,earth_association_score,chthonic_flag,serpent_flag,short_note)
SELECT id,name,trad,etype,cat,dom,'devotional',conf,'candidate_verified_name','Roster build via gen_roster.py (see CHANGELOG/git for release)',0,false,false,note FROM _e
ON CONFLICT (entity_id) DO NOTHING;

CREATE TEMP TABLE _s(id text,src text,etype text,note text) ON COMMIT DROP;
INSERT INTO _s VALUES
 ('ENT_ZOR_ZURVAN_AKARANA','SRC_ZAEHNER_ZURVAN','scholarly attestation','attestation'),
 ('ENT_ZOR_ZURVAN_DAREGHO','SRC_ZAEHNER_ZURVAN','scholarly attestation','attestation');

INSERT INTO entity_sources (entity_id,source_id,evidence_type,source_note)
SELECT s.id,s.src,s.etype,s.note FROM _s s
WHERE EXISTS(SELECT 1 FROM entities e WHERE e.entity_id=s.id) AND EXISTS(SELECT 1 FROM sources x WHERE x.source_id=s.src)
ON CONFLICT DO NOTHING;

CREATE TEMP TABLE _p(id text,per text,note text) ON COMMIT DROP;
INSERT INTO _p VALUES
 ('ENT_ZOR_ZURVAN_AKARANA','PER_ZOR_SASANIAN','Zurvan akarana, ''Boundless/Infinite Time'' — the unconditioned, eternal aspect of Zurvan from which the cosmos and the finite world-cycle proceed in Zurvanite speculation (Zaehner, Zurvan, esp. pp. 89-105 on the two zurvans).'),
 ('ENT_ZOR_ZURVAN_DAREGHO','PER_ZOR_SASANIAN','Zurvan daregho-chvadhata, ''Time of Long Dominion'' — the finite, measured time (the 9,000/12,000-year world-cycle) into which Boundless Time issues so that the conflict of Ohrmazd and Ahriman can be played out and resolved (Zaehner, Zurvan, pp. 89-105, 219ff.).');

INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
SELECT p.id,p.per,'high',p.note,(SELECT es.source_id FROM entity_sources es WHERE es.entity_id=p.id ORDER BY es.source_id LIMIT 1),'reviewed'
FROM _p p
WHERE EXISTS(SELECT 1 FROM entities e WHERE e.entity_id=p.id) AND EXISTS(SELECT 1 FROM periods x WHERE x.period_id=p.per)
ON CONFLICT DO NOTHING;

CREATE TEMP TABLE _r(s text,t text,o text,c text,ra text) ON COMMIT DROP;
INSERT INTO _r VALUES
 ('ENT_ZOR_AHURA_MAZDA','sibling_of','ENT_ZOR_ANGRA_MAINYU','high','In Zurvanism Ohrmazd and Ahriman are twin brothers, both born of Zurvan — distinct from orthodox Mazdaism where the antagonist of the destructive spirit is Spenta Mainyu, not Ahura Mazda himself (Zaehner, Zurvan, 1955).'),
 ('ENT_ZOR_ZURVAN_AKARANA','epithet_of','ENT_ZOR_ZURVAN','high','Zurvan akarana (''Boundless Time'') is the eternal/infinite aspect-name of the time-god Zurvan in the Pahlavi sources (Zaehner, Zurvan, 1955, pp. 89-105 on the doctrine of the two zurvans).'),
 ('ENT_ZOR_ZURVAN_DAREGHO','epithet_of','ENT_ZOR_ZURVAN','high','Zurvan daregho-chvadhata (''Time of Long Dominion'') is the finite, measured aspect-name of Zurvan — the bounded world-cycle issuing from Boundless Time (Zaehner, Zurvan, 1955, pp. 89-105).'),
 ('ENT_ZOR_ZURVAN_DAREGHO','emanates_from','ENT_ZOR_ZURVAN_AKARANA','medium','In the Zurvanite cosmology Finite Time (daregho-chvadhata), the 9,000/12,000-year cycle within which the cosmic battle unfolds, is carved out of / issues from Boundless Time (akarana) so that the conflict may reach resolution (Zaehner, Zurvan, 1955, pp. 219ff.).');

\echo '--- REJECTED edges (bad id/type, or subject lacks a source) — review these ---'
SELECT r.s,r.t,r.o FROM _r r
WHERE NOT (EXISTS(SELECT 1 FROM entities e WHERE e.entity_id=r.s)
  AND EXISTS(SELECT 1 FROM entities e WHERE e.entity_id=r.o)
  AND EXISTS(SELECT 1 FROM relationship_types y WHERE y.relationship_type=r.t)
  AND EXISTS(SELECT 1 FROM entity_sources es WHERE es.entity_id=r.s));

INSERT INTO entity_relationships(subject_entity_id,relationship_type,object_entity_id,confidence,rationale,source_id,review_status)
SELECT r.s,r.t,r.o,r.c,r.ra,
  (SELECT es.source_id FROM entity_sources es WHERE es.entity_id=r.s ORDER BY es.source_id LIMIT 1),'reviewed'
FROM _r r
WHERE EXISTS(SELECT 1 FROM entities e WHERE e.entity_id=r.s)
  AND EXISTS(SELECT 1 FROM entities e WHERE e.entity_id=r.o)
  AND EXISTS(SELECT 1 FROM relationship_types y WHERE y.relationship_type=r.t)
  AND EXISTS(SELECT 1 FROM entity_sources es WHERE es.entity_id=r.s)
ON CONFLICT (subject_entity_id,relationship_type,object_entity_id) DO NOTHING;

COMMIT;
